SELECT 'barangays_count' AS check_name, COUNT(*) AS count FROM barangays UNION ALL SELECT 'magsaysay_exists', COUNT(*) FROM barangays WHERE name = 'Magsaysay' UNION ALL SELECT 'responder_in_magsaysay', COUNT(*) FROM users WHERE role = 'responder' AND barangay = 'Magsaysay' AND is_approved = true AND responder_status = 'available' UNION ALL SELECT 'trg_match_exists', COUNT(*) FROM pg_trigger WHERE tgname = 'trg_match_responders' UNION ALL SELECT 'trg_update_location_exists', COUNT(*) FROM pg_trigger WHERE tgname = 'trg_update_incident_location';